/* F405: a caller-supplied reqwest::Client is the transport. The mock server
 * below records the raw request, so the test proves the request went through
 * the supplied client (its default header is on the wire) while the SDK's own
 * defaults (User-Agent) are still applied on top. */
#[tokio::test]
async fn test_bhv_langrust_035_default_api_client_with_client_sends_through_supplied_client() {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let addr = listener.local_addr().unwrap();
    let (tx, rx) = std::sync::mpsc::channel::<String>();
    std::thread::spawn(move || {
        if let Some(stream) = listener.incoming().next() {
            let mut stream = stream.unwrap();
            let mut buf = [0u8; 4096];
            let n = std::io::Read::read(&mut stream, &mut buf).unwrap_or(0);
            let _ = tx.send(String::from_utf8_lossy(&buf[..n]).to_string());
            let response = "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\n{}";
            let _ = std::io::Write::write_all(&mut stream, response.as_bytes());
        }
    });

    let mut default_headers = reqwest::header::HeaderMap::new();
    default_headers.insert(
        "x-supplied-client",
        reqwest::header::HeaderValue::from_static("yes"),
    );
    let supplied = reqwest::Client::builder()
        .default_headers(default_headers)
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .expect("client builds");
    let transport = TransportOptionsBuilder::new()
        .user_agent("sdk-agent/1.0")
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::with_client(supplied, Some(transport)).expect("no conflict");

    let resp = client
        .send_request(
            "GET",
            &format!("http://{}/probe", addr),
            &HashMap::new(),
            None,
        )
        .await
        .expect("request through the supplied client");
    assert_eq!(resp.status_code(), 200);

    let raw = rx
        .recv_timeout(std::time::Duration::from_secs(5))
        .expect("request captured")
        .to_lowercase();
    assert!(
        raw.contains("x-supplied-client: yes"),
        "supplied client header missing: {}",
        raw
    );
    assert!(
        raw.contains("user-agent: sdk-agent/1.0"),
        "SDK user agent missing: {}",
        raw
    );
}

/* F405: closing the SDK client never shuts down a caller-supplied client; the
 * caller's handle keeps sending requests afterwards. */
#[tokio::test]
async fn test_bhv_lifecycle_045_default_api_client_close_leaves_supplied_client_usable() {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let url = format!("http://{}/", listener.local_addr().unwrap());
    std::thread::spawn(move || {
        for stream in listener.incoming().take(2) {
            let mut stream = stream.unwrap();
            let mut buf = [0u8; 4096];
            let _ = std::io::Read::read(&mut stream, &mut buf);
            let _ = std::io::Write::write_all(
                &mut stream,
                b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
            );
        }
    });
    let supplied = reqwest::Client::new();
    let client = DefaultApiClient::with_client(supplied.clone(), None).expect("no conflict");
    assert!(supplied.get(&url).send().await.is_ok());
    client.close();
    assert!(client.is_closed());
    let response = supplied
        .get(&url)
        .send()
        .await
        .expect("the supplied client must still send");
    assert_eq!(200, response.status().as_u16());
}

/* lifecycle 024: a supplied client conflicts with the SDK proxy and TLS settings, each refused. */
#[test]
fn test_bhv_lifecycle_024_a_supplied_client_conflicts_with_proxy_and_tls_settings() {
    let ca_path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/certs/ca.pem");
    let options = [
        TransportOptionsBuilder::new()
            .proxy("http://proxy.invalid:3128")
            .build(),
        TransportOptionsBuilder::new().verify_ssl(false).build(),
        TransportOptionsBuilder::new().ca_cert_path(ca_path).build(),
    ];
    for built in options {
        let transport = built.expect("valid transport options");
        match DefaultApiClient::with_client(reqwest::Client::new(), Some(transport)) {
            Err(ConfigurationError::InvalidArgument(message)) => {
                assert!(
                    message.contains("custom reqwest::Client"),
                    "unexpected message: {}",
                    message
                );
            }
            Err(other) => panic!("expected InvalidArgument, got {:?}", other),
            Ok(_) => panic!("expected a conflict error, got a client"),
        }
    }
}

/// Starts a local server that counts the connections it accepts and answers each one after `delay_ms`.
fn start_counting_server(
    delay_ms: u64,
) -> (String, std::sync::Arc<std::sync::atomic::AtomicUsize>) {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let url = format!("http://{}/", listener.local_addr().unwrap());
    let accepted = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let counter = accepted.clone();
    std::thread::spawn(move || {
        for stream in listener.incoming() {
            let Ok(mut stream) = stream else { break };
            counter.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            std::thread::spawn(move || {
                let mut buf = [0u8; 4096];
                let _ = std::io::Read::read(&mut stream, &mut buf);
                std::thread::sleep(std::time::Duration::from_millis(delay_ms));
                let _ = std::io::Write::write_all(
                    &mut stream,
                    b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                );
            });
        }
    });
    (url, accepted)
}

/// A supplied client combined with SDK redirect settings is a conflict, refused at construction.
#[test]
fn test_bhv_lifecycle_041_a_supplied_client_with_redirect_settings_is_a_conflict() {
    let transport = TransportOptionsBuilder::new()
        .max_redirects(Some(3))
        .build()
        .expect("valid transport options");
    match DefaultApiClient::with_client(reqwest::Client::new(), Some(transport)) {
        Err(ConfigurationError::InvalidArgument(message)) => {
            assert!(
                message.contains("custom reqwest::Client"),
                "unexpected message: {}",
                message
            );
        }
        Err(other) => panic!("expected InvalidArgument, got {:?}", other),
        Ok(_) => panic!("expected a conflict error, got a client"),
    }
}

/// A caller-supplied HTTP client carries the requests: the server receives them through it.
#[tokio::test]
async fn test_bhv_lifecycle_042_a_supplied_http_client_sends_the_requests() {
    let (url, accepted) = start_counting_server(0);
    let client = DefaultApiClient::with_client(reqwest::Client::new(), None).expect("no conflict");
    let response = client
        .send_request("GET", &url, &HashMap::new(), None)
        .await
        .expect("the request must go through the supplied client");
    assert_eq!(200, response.status_code());
    assert_eq!(1, accepted.load(std::sync::atomic::Ordering::SeqCst));
}

/// After close, a new request fails with a closed-client error and never reaches the network.
#[tokio::test]
async fn test_bhv_lifecycle_043_a_request_after_close_fails_without_reaching_the_network() {
    let (url, accepted) = start_counting_server(0);
    let client = DefaultApiClient::new(None);
    client.close();
    let err = client
        .send_request("GET", &url, &HashMap::new(), None)
        .await
        .expect_err("a closed client must refuse the request");
    assert!(err.to_string().contains("closed"), "{}", err);
    assert_eq!(0, accepted.load(std::sync::atomic::Ordering::SeqCst));
}

/// A request already in flight when the client is closed still completes successfully.
#[tokio::test]
async fn test_bhv_lifecycle_044_a_request_in_flight_when_the_client_closes_still_completes() {
    let (url, _accepted) = start_counting_server(300);
    let client = std::sync::Arc::new(DefaultApiClient::new(None));
    let in_flight = {
        let client = client.clone();
        let url = url.clone();
        tokio::spawn(async move {
            client
                .send_request("GET", &url, &HashMap::new(), None)
                .await
        })
    };
    tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    client.close();
    let response = in_flight
        .await
        .expect("the task must not panic")
        .expect("the in-flight request must complete after close");
    assert_eq!(200, response.status_code());
}

#[tokio::test]
async fn test_bhv_misc_266_caller_default_headers_replace_user_agent_and_request_id_any_case() {
    let chasm_url = testcontainers_helper::chasm_http_url();
    let transport = TransportOptionsBuilder::new()
        .user_agent("SdkDefault/1.0")
        .inject_request_id(true)
        .default_header("USER-agent", "Caller/2.0")
        .default_header("x-REQUEST-id", "caller-request-7")
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));
    let resp = client
        .send_request(
            "GET",
            &format!("{}/test/echo", chasm_url),
            &HashMap::new(),
            None,
        )
        .await
        .expect("unexpected error");

    let json: serde_json::Value = serde_json::from_str(resp.body()).expect("invalid json");
    let h = &json["headers"];
    assert_eq!(
        h.get("user-agent").and_then(|v| v.as_str()),
        Some("Caller/2.0")
    );
    assert_eq!(
        h.get("x-request-id").and_then(|v| v.as_str()),
        Some("caller-request-7")
    );
}

#[tokio::test]
async fn test_bhv_misc_269_self_signed_endpoint_is_reached_only_when_verification_is_off() {
    let chasm_url = testcontainers_helper::chasm_https_url();
    let off = TransportOptionsBuilder::new()
        .verify_ssl(false)
        .build()
        .expect("valid transport options");
    let on = TransportOptionsBuilder::new()
        .verify_ssl(true)
        .build()
        .expect("valid transport options");

    let reached = DefaultApiClient::new(Some(off))
        .send_request(
            "GET",
            &format!("{}/test/echo", chasm_url),
            &HashMap::new(),
            None,
        )
        .await
        .expect("self-signed endpoint must be reached with verification off");
    assert_eq!(reached.status_code(), 200);

    let refused = DefaultApiClient::new(Some(on))
        .send_request(
            "GET",
            &format!("{}/test/echo", chasm_url),
            &HashMap::new(),
            None,
        )
        .await;
    assert!(
        refused.is_err(),
        "self-signed endpoint must be rejected with verification on"
    );
}
#[tokio::test]
async fn test_bhv_misc_267_a_caller_supplied_http_client_default_headers_are_sent_with_each_request(
) {
    let chasm_url = testcontainers_helper::chasm_http_url();
    let mut defaults = reqwest::header::HeaderMap::new();
    defaults.insert(
        "x-pool-default",
        reqwest::header::HeaderValue::from_static("yes"),
    );
    let http = reqwest::Client::builder()
        .default_headers(defaults)
        .build()
        .expect("valid client");
    let client = DefaultApiClient::with_client(http, None).expect("valid client");
    let resp = client
        .send_request(
            "GET",
            &format!("{}/test/echo", chasm_url),
            &HashMap::new(),
            None,
        )
        .await
        .expect("unexpected error");
    let json: serde_json::Value = serde_json::from_str(resp.body()).expect("invalid json");
    assert_eq!(Some("yes"), json["headers"]["x-pool-default"].as_str());
}

#[tokio::test]
async fn test_bhv_misc_268_a_trusted_ca_certificate_is_rejected_when_the_hostname_does_not_match() {
    use std::net::ToSocketAddrs;
    let https_url = testcontainers_helper::chasm_https_url();
    let (host, port) = https_url
        .trim_start_matches("https://")
        .rsplit_once(':')
        .expect("the https url must carry a port");
    let ip = (host, 0u16)
        .to_socket_addrs()
        .expect("the fixture host resolves")
        .next()
        .expect("an address")
        .ip();
    let transport = TransportOptionsBuilder::new()
        .verify_ssl(true)
        .ca_cert_path(testcontainers_helper::ca_cert_path())
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));
    let err = client
        .send_request(
            "GET",
            &format!("https://{}:{}/test/echo", ip, port),
            &HashMap::new(),
            None,
        )
        .await
        .expect_err("a certificate for another host must be rejected");
    assert!(
        err.downcast_ref::<petstore::NetworkError>().is_some(),
        "{}",
        err
    );
}

#[tokio::test]
async fn test_bhv_misc_271_a_client_without_a_proxy_connects_directly() {
    let chasm_url = testcontainers_helper::chasm_http_url();
    let variables = [
        "HTTP_PROXY",
        "http_proxy",
        "HTTPS_PROXY",
        "https_proxy",
        "ALL_PROXY",
        "all_proxy",
    ];
    for name in variables {
        std::env::set_var(name, "http://127.0.0.1:1");
    }
    for name in ["NO_PROXY", "no_proxy"] {
        std::env::remove_var(name);
    }
    let client = DefaultApiClient::new(None);
    let resp = client
        .send_request(
            "GET",
            &format!("{}/test/echo", chasm_url),
            &HashMap::new(),
            None,
        )
        .await
        .expect("a direct connection must succeed");
    for name in variables {
        std::env::remove_var(name);
    }
    assert_eq!(200, resp.status_code());
}

